using System.Collections.Concurrent;
using System.Diagnostics;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
namespace CombatSolver;
internal static class TaskMutationEpochs
{
    private sealed class Epoch
    {
        internal MirroredHookListenerFilter? Filter;
        internal readonly PredictedCard?[] Cards = new PredictedCard?[8];
        internal int Count;
        internal bool Overflow;
        internal long Writes;
        internal bool Inherited;
        internal bool Active => Filter is not null;
        internal void Add(PredictedCard card)
        {
            Writes++;
            if (Overflow) return;
            for (int i=0;i<Count;i++) if (ReferenceEquals(Cards[i],card)) return;
            if (Count==8) { Overflow=true; return; }
            Cards[Count++]=card;
        }
        internal void Clear()
        { Array.Clear(Cards); Filter=null; Count=0; Overflow=false; Writes=0; Inherited=false; }
    }
    private static readonly ConditionalWeakTable<SimCardPile,Epoch> Epochs=new();
    private static readonly ConcurrentQueue<string> Stacks=new();
    private static int StackCount;
    [ThreadStatic] private static long[]? _counts;
    private static readonly ConcurrentBag<long[]> Cells=new();
    // 0..9: distinct count (9=>=9), each with calls/card-weight/writes/fork-inherited.
    private static long[] Counts()
    { if (_counts is {} c) return c; _counts=new long[48]; Cells.Add(_counts); return _counts; }
    static TaskMutationEpochs()
    {
        AppDomain.CurrentDomain.ProcessExit+=(_,_)=>
        {
            string? path=Environment.GetEnvironmentVariable("COMBATSOLVER_TASK_MUTATION_EPOCHS_OUT"); if(path is null)return;
            long[] sums=new long[48]; foreach(long[] cell in Cells)for(int i=0;i<sums.Length;i++)sums[i]+=cell[i];
            var bins=Enumerable.Range(0,10).Select(i=>new{Distinct=i==9?">=9":i.ToString(),Queries=sums[i*4],CardWeightedQueries=sums[i*4+1],MutationCalls=sums[i*4+2],InheritedQueries=sums[i*4+3]}).ToArray();
            File.WriteAllText(path,JsonSerializer.Serialize(new{Bins=bins,ExplicitInvalidations=sums[40],MembershipInvalidations=sums[41],RemovedTrackedCards=sums[42],ForkMissingRemaps=sums[43],FilterMismatches=sums[44],ForkCaptures=sums[45],FirstMultipleWrites=Stacks.ToArray(),ThreadCells=Cells.Count,Scope="diagnostic epochs anchored in previously certified empty projections; not performance or pruning evidence"},new JsonSerializerOptions{WriteIndented=true}));
        };
    }
    internal static void Mark(SimCardPile pile,PredictedCard card,MirroredHookListenerFilter? anchor,PredictedCard? pending)
    {
        bool exists=Epochs.TryGetValue(pile,out Epoch? e);
        if(!exists || !e!.Active)
        {
            if(anchor is null)return;
            e=Epochs.GetValue(pile,static _=>new Epoch()); e.Filter=anchor;
            if(pending is not null)e.Add(pending);
        }
        int before=e!.Count; bool overflow=e.Overflow; e.Add(card);
        if(!overflow && before==1 && e.Count==2 && Interlocked.Increment(ref StackCount)<=8)
            Stacks.Enqueue(pile.Type+" count="+pile.Cards.Count+Environment.NewLine+new StackTrace(false));
    }
    internal static void Query(SimCardPile pile,MirroredHookListenerFilter filter,MirroredHookListenerFilter? anchor,PredictedCard? pending)
    {
        if(!Epochs.TryGetValue(pile,out Epoch? e) || !e.Active)
        {
            if(anchor is null || pending is null)return;
            e=Epochs.GetValue(pile,static _=>new Epoch()); e.Filter=anchor; e.Add(pending); e.Inherited=true;
        }
        long[] c=Counts();
        if(!ReferenceEquals(e.Filter,filter)){c[44]++;e.Clear();return;}
        int bucket=e.Overflow?9:e.Count; c[bucket*4]++;c[bucket*4+1]+=pile.Cards.Count;c[bucket*4+2]+=e.Writes;if(e.Inherited)c[bucket*4+3]++;
        e.Clear();
    }
    internal static void Membership(SimCardPile pile,bool retained,PredictedCard? removed)
    {
        if(!Epochs.TryGetValue(pile,out Epoch? e)||!e.Active)return;
        if(!retained){Counts()[41]++;e.Clear();return;}
        if(removed is null||e.Overflow)return;
        for(int i=0;i<e.Count;i++)if(ReferenceEquals(e.Cards[i],removed))
        {e.Cards[i]=e.Cards[--e.Count];e.Cards[e.Count]=null;Counts()[42]++;break;}
    }
    internal static void Invalidate(SimCardPile pile)
    {if(Epochs.TryGetValue(pile,out Epoch? e)&&e.Active){Counts()[40]++;e.Clear();}}
    internal static void Fork(SimCardPile parent,SimCardPile child,PredictionForkContext context)
    {
        if(!Epochs.TryGetValue(parent,out Epoch? source)||!source.Active)return;
        Epoch target=Epochs.GetValue(child,static _=>new Epoch());target.Filter=source.Filter;target.Overflow=source.Overflow;target.Writes=source.Writes;target.Inherited=true;
        for(int i=0;i<source.Count;i++)
        {
            if(!context.TryRemap(source.Cards[i]!,out PredictedCard? mapped)){Counts()[43]++;target.Clear();return;}
            target.Cards[target.Count++]=mapped;
        }
        Counts()[45]++;
    }
}

